mapper.select:
select u.user_id, u.dept_id, (select lu.user_id from sys_user lu where lu.user_name = d.leader and lu.del_flag = '0' and lu.status = '0' order by case when lu.dept_id = d.dept_id then 0 else 1 end, lu.user_id limit 1) as reviewer_id from sys_user u inner join sys_dept d on d.dept_id = u.dept_id where u.del_flag = '0' and u.status = '0' and u.dept_id in
#{deptId}
order by u.dept_id, u.user_id
